const config = {
  "previewFeatures": [
    "driverAdapters"
  ],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// =============================================================\n// JKA Bangladesh — Prisma Schema\n// PostgreSQL via Supabase · Prisma 7 · driverAdapters preview\n// =============================================================\n\ngenerator client {\n  provider        = \"prisma-client-js\"\n  output          = \"../prisma/generated/client\"\n  previewFeatures = [\"driverAdapters\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─────────────────────────────────────────────\n// ENUMS\n// ─────────────────────────────────────────────\n\nenum MemberRole {\n  STUDENT\n  INSTRUCTOR\n  ADMIN\n}\n\nenum GradingResult {\n  PASSED\n  FAILED\n  ABSENT\n}\n\nenum ApplicationStatus {\n  SUBMITTED\n  APPROVED\n  REJECTED\n}\n\nenum PaymentStatus {\n  PENDING\n  PAID\n  FAILED\n  REFUNDED\n}\n\nenum NotificationType {\n  INFO\n  WARNING\n  SUCCESS\n  PAYMENT\n  GRADING\n  EVENT\n  RENEWAL\n}\n\n// ─────────────────────────────────────────────\n// BELT RANKS\n// ─────────────────────────────────────────────\n\nmodel BeltRank {\n  id          String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name_en     String  @unique\n  name_bn     String?\n  kyu_dan     String?\n  color_hex   String?\n  order_index Int     @unique\n\n  // Relations\n  gradings_from        Grading[]            @relation(\"GradingFromRank\")\n  gradings_to          Grading[]            @relation(\"GradingToRank\")\n  grading_events       GradingEvent[]       @relation(\"EventTargetRank\")\n  grading_applications GradingApplication[] @relation(\"AppTargetRank\")\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@map(\"belt_ranks\")\n}\n\n// ─────────────────────────────────────────────\n// DOJOS\n// ─────────────────────────────────────────────\n\nmodel Dojo {\n  id        String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name      String\n  name_en   String?\n  name_bn   String?\n  address   String?\n  city      String?\n  latitude  Float?\n  longitude Float?\n  phone     String?\n  email     String?\n  schedule  Json? // Weekly schedule JSON\n  is_active Boolean @default(true)\n\n  head_instructor_id String? @db.Uuid\n\n  // Relations\n  head_instructor Member?      @relation(\"DojoHeadInstructor\", fields: [head_instructor_id], references: [id])\n  members         Member[]     @relation(\"DojoMembers\")\n  instructors     Instructor[]\n  attendance      Attendance[]\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@map(\"dojos\")\n}\n\n// ─────────────────────────────────────────────\n// MEMBERS  (mirrors auth.users via id)\n// ─────────────────────────────────────────────\n\nmodel Member {\n  id            String     @id @db.Uuid // = auth.users.id\n  full_name     String\n  email         String     @unique\n  phone         String?\n  avatar_url    String?\n  role          MemberRole @default(STUDENT)\n  member_number String?    @unique\n  current_rank  String     @default(\"White Belt\")\n  join_date     DateTime   @default(now())\n  expiry_date   DateTime?\n  is_active     Boolean    @default(true)\n  dojo_id       String?    @db.Uuid\n\n  // Relations\n  dojo                 Dojo?                   @relation(\"DojoMembers\", fields: [dojo_id], references: [id])\n  dojo_head_of         Dojo[]                  @relation(\"DojoHeadInstructor\")\n  instructor           Instructor?\n  admin                Admin?\n  gradings             Grading[]\n  grading_applications GradingApplication[]\n  event_registrations  EventRegistration[]\n  notifications        Notification[]\n  orders               ShopOrder[]\n  attendance           Attendance[]\n  tournament_entries   TournamentParticipant[]\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@map(\"members\")\n}\n\n// ─────────────────────────────────────────────\n// ADMINS  (super-admin elevation)\n// ─────────────────────────────────────────────\n\nmodel Admin {\n  id        String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  member_id String  @unique @db.Uuid\n  notes     String?\n\n  member Member @relation(fields: [member_id], references: [id], onDelete: Cascade)\n\n  created_at DateTime @default(now())\n\n  @@map(\"admins\")\n}\n\n// ─────────────────────────────────────────────\n// INSTRUCTORS\n// ─────────────────────────────────────────────\n\nmodel Instructor {\n  id        String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  member_id String  @unique @db.Uuid\n  dojo_id   String? @db.Uuid\n  bio       String?\n  bio_en    String?\n  bio_bn    String?\n  is_active Boolean @default(true)\n\n  member Member @relation(fields: [member_id], references: [id], onDelete: Cascade)\n  dojo   Dojo?  @relation(fields: [dojo_id], references: [id])\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@map(\"instructors\")\n}\n\n// ─────────────────────────────────────────────\n// ATTENDANCE\n// ─────────────────────────────────────────────\n\nmodel Attendance {\n  id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  member_id String   @db.Uuid\n  dojo_id   String?  @db.Uuid\n  date      DateTime @db.Date\n  present   Boolean  @default(true)\n  notes     String?\n\n  member Member @relation(fields: [member_id], references: [id], onDelete: Cascade)\n  dojo   Dojo?  @relation(fields: [dojo_id], references: [id])\n\n  created_at DateTime @default(now())\n\n  @@unique([member_id, date])\n  @@map(\"attendance\")\n}\n\n// ─────────────────────────────────────────────\n// GRADING EVENTS  (exam sessions)\n// ─────────────────────────────────────────────\n\nmodel GradingEvent {\n  id             String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name           String\n  event_date     DateTime\n  location       String?\n  target_rank_id String?  @db.Uuid\n  is_open        Boolean  @default(true)\n  notes          String?\n\n  target_rank  BeltRank?            @relation(\"EventTargetRank\", fields: [target_rank_id], references: [id])\n  gradings     Grading[]\n  applications GradingApplication[]\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@map(\"grading_events\")\n}\n\n// ─────────────────────────────────────────────\n// GRADING APPLICATIONS\n// ─────────────────────────────────────────────\n\nmodel GradingApplication {\n  id               String            @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  member_id        String            @db.Uuid\n  grading_event_id String            @db.Uuid\n  target_rank_id   String?           @db.Uuid\n  status           ApplicationStatus @default(SUBMITTED)\n  notes            String?\n  applied_at       DateTime          @default(now())\n\n  member        Member       @relation(fields: [member_id], references: [id], onDelete: Cascade)\n  grading_event GradingEvent @relation(fields: [grading_event_id], references: [id], onDelete: Cascade)\n  target_rank   BeltRank?    @relation(\"AppTargetRank\", fields: [target_rank_id], references: [id])\n\n  @@unique([member_id, grading_event_id])\n  @@map(\"grading_applications\")\n}\n\n// ─────────────────────────────────────────────\n// GRADINGS  (results)\n// ─────────────────────────────────────────────\n\nmodel Grading {\n  id               String        @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  member_id        String        @db.Uuid\n  grading_event_id String?       @db.Uuid\n  from_rank_id     String?       @db.Uuid\n  to_rank_id       String?       @db.Uuid\n  result           GradingResult @default(PASSED)\n  certificate_url  String?\n  notes            String?\n\n  member        Member        @relation(fields: [member_id], references: [id], onDelete: Cascade)\n  grading_event GradingEvent? @relation(fields: [grading_event_id], references: [id])\n  from_rank     BeltRank?     @relation(\"GradingFromRank\", fields: [from_rank_id], references: [id])\n  to_rank       BeltRank?     @relation(\"GradingToRank\", fields: [to_rank_id], references: [id])\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@map(\"gradings\")\n}\n\n// ─────────────────────────────────────────────\n// EVENTS  (public events, managed via CMS)\n// ─────────────────────────────────────────────\n\nmodel Event {\n  id           String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  title        String\n  title_en     String?\n  title_bn     String?\n  description  String?\n  event_date   DateTime\n  location     String?\n  image_url    String?\n  is_published Boolean  @default(false)\n  max_capacity Int?\n\n  registrations EventRegistration[]\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@map(\"events\")\n}\n\n// ─────────────────────────────────────────────\n// EVENT REGISTRATIONS\n// ─────────────────────────────────────────────\n\nmodel EventRegistration {\n  id        String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  event_id  String @db.Uuid\n  member_id String @db.Uuid\n\n  event  Event  @relation(fields: [event_id], references: [id], onDelete: Cascade)\n  member Member @relation(fields: [member_id], references: [id], onDelete: Cascade)\n\n  created_at DateTime @default(now())\n\n  @@unique([event_id, member_id])\n  @@map(\"event_registrations\")\n}\n\n// ─────────────────────────────────────────────\n// NOTIFICATIONS\n// ─────────────────────────────────────────────\n\nmodel Notification {\n  id        String           @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  member_id String           @db.Uuid\n  title     String\n  message   String\n  type      NotificationType @default(INFO)\n  is_read   Boolean          @default(false)\n  link      String?\n\n  member Member @relation(fields: [member_id], references: [id], onDelete: Cascade)\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@map(\"notifications\")\n}\n\n// ─────────────────────────────────────────────\n// SHOP PRODUCTS\n// ─────────────────────────────────────────────\n\nmodel ShopProduct {\n  id          String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name        String\n  name_en     String?\n  name_bn     String?\n  description String?\n  price       Decimal @db.Decimal(10, 2)\n  stock       Int     @default(0)\n  image_url   String?\n  is_active   Boolean @default(true)\n\n  order_items ShopOrderItem[]\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@map(\"shop_products\")\n}\n\n// ─────────────────────────────────────────────\n// SHOP ORDERS\n// ─────────────────────────────────────────────\n\nmodel ShopOrder {\n  id             String        @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  member_id      String        @db.Uuid\n  payment_status PaymentStatus @default(PENDING)\n  payment_method String?\n  total          Decimal       @db.Decimal(10, 2)\n  currency       String        @default(\"BDT\")\n  transaction_id String?       @unique\n  notes          String?\n\n  member      Member          @relation(fields: [member_id], references: [id], onDelete: Cascade)\n  order_items ShopOrderItem[]\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@map(\"shop_orders\")\n}\n\n// ─────────────────────────────────────────────\n// SHOP ORDER ITEMS  (line items)\n// ─────────────────────────────────────────────\n\nmodel ShopOrderItem {\n  id         String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  order_id   String  @db.Uuid\n  product_id String  @db.Uuid\n  quantity   Int\n  unit_price Decimal @db.Decimal(10, 2)\n\n  order   ShopOrder   @relation(fields: [order_id], references: [id], onDelete: Cascade)\n  product ShopProduct @relation(fields: [product_id], references: [id])\n\n  @@map(\"shop_order_items\")\n}\n\n// ─────────────────────────────────────────────\n// TOURNAMENTS\n// ─────────────────────────────────────────────\n\nmodel Tournament {\n  id           String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name         String\n  name_en      String?\n  name_bn      String?\n  description  String?\n  date         DateTime\n  location     String?\n  is_published Boolean  @default(false)\n\n  participants TournamentParticipant[]\n  matches      TournamentMatch[]\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@map(\"tournaments\")\n}\n\n// ─────────────────────────────────────────────\n// TOURNAMENT PARTICIPANTS\n// ─────────────────────────────────────────────\n\nmodel TournamentParticipant {\n  id            String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tournament_id String  @db.Uuid\n  member_id     String  @db.Uuid\n  category      String?\n  weight_class  String?\n\n  tournament Tournament @relation(fields: [tournament_id], references: [id], onDelete: Cascade)\n  member     Member     @relation(fields: [member_id], references: [id], onDelete: Cascade)\n\n  matches_as_p1 TournamentMatch[] @relation(\"MatchParticipant1\")\n  matches_as_p2 TournamentMatch[] @relation(\"MatchParticipant2\")\n  matches_won   TournamentMatch[] @relation(\"MatchWinner\")\n\n  created_at DateTime @default(now())\n\n  @@unique([tournament_id, member_id])\n  @@map(\"tournament_participants\")\n}\n\n// ─────────────────────────────────────────────\n// TOURNAMENT MATCHES\n// ─────────────────────────────────────────────\n\nmodel TournamentMatch {\n  id              String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tournament_id   String  @db.Uuid\n  participant1_id String? @db.Uuid\n  participant2_id String? @db.Uuid\n  winner_id       String? @db.Uuid\n  round           Int?\n  match_order     Int?\n  notes           String?\n\n  tournament   Tournament             @relation(fields: [tournament_id], references: [id], onDelete: Cascade)\n  participant1 TournamentParticipant? @relation(\"MatchParticipant1\", fields: [participant1_id], references: [id])\n  participant2 TournamentParticipant? @relation(\"MatchParticipant2\", fields: [participant2_id], references: [id])\n  winner       TournamentParticipant? @relation(\"MatchWinner\", fields: [winner_id], references: [id])\n\n  created_at DateTime @default(now())\n\n  @@map(\"tournament_matches\")\n}\n"
}

